-- Only promote untouched non-art drafts. Art records and editor changes are protected.
begin;
create temporary table kk_art_changed(id uuid primary key) on commit drop;
with changed as (
 insert into public.kk_museums as m(id,inventory_key,name,city,province,street_address,postal_code,country,website_url,latitude,longitude,summary,operating_status,publication_status,verification_status,tags,photos,is_art_museum)
 select id,inventory_key,name,city,province,street_address,postal_code,country,website_url,latitude,longitude,summary,operating_status,publication_status,verification_status,tags,photos,is_art_museum from jsonb_populate_recordset(null::public.kk_museums,'[{"id":"35b67e78-bbd8-5bae-8a83-9612565a6d35","inventory_key":"art-audit:307","name":"Dat Bolwerck - Huis voor kunst en gedachten","city":"Zutphen","province":"Gelderland","street_address":"Zaadmarkt 112","postal_code":"7201 DE","country":"NL","website_url":"https://www.datbolwerck.nl/","latitude":null,"longitude":null,"summary":"Ontdek hedendaagse kunst in de historische ruimtes van Dat Bolwerck. Wisselende tentoonstellingen verbinden kijken met denken en gesprek. De persoonlijke schaal van het huis geeft ruimte aan aandachtige ontmoetingen met kunstwerken.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["hedendaagse kunst","kunsthal"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/36/Dat_Bolwerck_te_Zutphen_gefotografeerd_door_Rembrandt_Kalkhoven.jpg/1280px-Dat_Bolwerck_te_Zutphen_gefotografeerd_door_Rembrandt_Kalkhoven.jpg","caption":"Dat Bolwerck - Huis voor kunst en gedachten — Dat Bolwerck te Zutphen gefotografeerd door Rembrandt Kalkhoven","credit":"Kalkhoven","source_url":"https://commons.wikimedia.org/wiki/File:Dat_Bolwerck_te_Zutphen_gefotografeerd_door_Rembrandt_Kalkhoven.jpg","license":"CC BY-SA 4.0"}],"is_art_museum":true},{"id":"8c9ac3bc-ff2a-5358-a726-de3a3a7ff7b7","inventory_key":"art-audit:308","name":"STRAAT Museum","city":"Amsterdam","province":"Noord-Holland","street_address":"NDSM-Plein 1","postal_code":"1033 WC","country":"NL","website_url":"https://straatmuseum.com/nl","latitude":null,"longitude":null,"summary":"Ontdek street art op grote schaal in een voormalige scheepsloods. STRAAT brengt kunstenaars uit verschillende landen samen met uiteenlopende stijlen en technieken. De monumentale werken laten zien hoe veelzijdig kunst uit de straat kan zijn.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["street art","graffiti","hedendaagse kunst"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a2/2022_Inside_the_Straat_Museum_for_Street_Art_and_Graffiti_-_Amsterdam%2C_Netherlands.jpg/1280px-2022_Inside_the_Straat_Museum_for_Street_Art_and_Graffiti_-_Amsterdam%2C_Netherlands.jpg","caption":"STRAAT Museum — 2022 Inside the Straat Museum for Street Art and Graffiti - Amsterdam, Netherlands","credit":"Joe Ross","source_url":"https://commons.wikimedia.org/wiki/File:2022_Inside_the_Straat_Museum_for_Street_Art_and_Graffiti_-_Amsterdam,_Netherlands.jpg","license":"CC BY-SA 2.0"}],"is_art_museum":true},{"id":"0163ec3a-fdc1-5298-9c1b-4f4ed0e807f9","inventory_key":"art-audit:309","name":"033Fotostad | Rietveldpaviljoen","city":"Amersfoort","province":"Utrecht","street_address":"Zonnehof 8","postal_code":"3811 ND","country":"NL","website_url":"https://www.033fotostad.com/","latitude":null,"longitude":null,"summary":"Ontdek fotografie in het Rietveldpaviljoen. Wisselende tentoonstellingen geven ruimte aan verschillende makers en beeldverhalen. De lichte architectuur vormt een helder decor om foto''s aandachtig te bekijken en met elkaar te vergelijken.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["fotografie","kunsthal"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/24/Amersfoort_Paviljoen_De_Zonnehof_seen_from_the_north.jpg/1280px-Amersfoort_Paviljoen_De_Zonnehof_seen_from_the_north.jpg","caption":"033Fotostad | Rietveldpaviljoen — Amersfoort Paviljoen De Zonnehof seen from the north","credit":"Ymblanter","source_url":"https://commons.wikimedia.org/wiki/File:Amersfoort_Paviljoen_De_Zonnehof_seen_from_the_north.jpg","license":"CC BY-SA 4.0"}],"is_art_museum":true},{"id":"8f412324-f19e-5dae-a2ab-b3579ec40695","inventory_key":"art-audit:314","name"