en","publication_status":"draft","verification_status":"unreviewed","tags":["hedendaagse kunst","kunsthal"],"photos":[],"is_art_museum":true},{"id":"b72de5cb-384d-54e4-8e70-d924679a875a","inventory_key":"art-audit:z41","name":"Kunsthuis Syb","city":"Beetsterzwaag","province":"Friesland","street_address":"Hoofdstraat 70","postal_code":"9244 CP","country":"NL","website_url":"https://www.kunsthuissyb.nl/","latitude":null,"longitude":null,"summary":"Ontdek kunst die ontstaat uit tijd, onderzoek en samenwerking. Kunsthuis SYB ontvangt kunstenaars en presenteert hun werk in tentoonstellingen en publieke momenten. Het huis in Beetsterzwaag biedt een intieme omgeving voor nieuwe ideeën.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["hedendaagse kunst","experiment","kunsthal"],"photos":[],"is_art_museum":true},{"id":"77dcd5d7-e549-53f5-b6cf-9d900113e0fe","inventory_key":"art-audit:z43","name":"Kunstpodium T","city":"Tilburg","province":"Noord-Brabant","street_address":"Noordstraat 105","postal_code":"5038 EH","country":"NL","website_url":"https://kunstpodium-t.com","latitude":null,"longitude":null,"summary":"Ontmoet kunstenaars aan het begin van hun ontwikkeling. Kunstpodium T brengt talent samen in tentoonstellingen en gezamenlijke projecten. De presentaties laten zien hoe eigen stijlen groeien door uitwisseling en experiment.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["hedendaagse kunst","jong talent","kunsthal"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/53/Noordstraat_105%2C_Tilburg.jpg/1280px-Noordstraat_105%2C_Tilburg.jpg","caption":"Kunstpodium T — Noordstraat 105, Tilburg","credit":"Rosemoon","source_url":"https://commons.wikimedia.org/wiki/File:Noordstraat_105,_Tilburg.jpg","license":"CC BY-SA 4.0"}],"is_art_museum":true}]'::jsonb)
 on conflict(id) do update set inventory_key=excluded.inventory_key,name=excluded.name,city=excluded.city,province=excluded.province,street_address=excluded.street_address,postal_code=excluded.postal_code,country=excluded.country,website_url=excluded.website_url,latitude=excluded.latitude,longitude=excluded.longitude,summary=excluded.summary,operating_status=excluded.operating_status,publication_status=excluded.publication_status,verification_status=excluded.verification_status,tags=excluded.tags,photos=excluded.photos,is_art_museum=excluded.is_art_museum
 where not m.is_art_museum and m.publication_status='draft'
 and not exists(select 1 from kunstkiezer_private.museum_changes c where c.museum_id=m.id and c.editor_id is not null)
 returning id
) insert into kk_art_changed select id from changed;
insert into public.kk_museum_editorial(museum_id,review_notes,suggested_tags)
